            1: tb_gname = "change returned 10 + 10 + 25";
            2: tb_gname = "maximum change 25 + 25";
            3: tb_gname = "six nickels";
            4: tb_gname = "no coin keeps the credit";
            5: tb_gname = "reset clears the credit";
            6: tb_gname = "1500 random coin sequences";
            default: tb_gname = "?";
        endcase
