    function real tb_abs(input real x);
        tb_abs = x < 0.0 ? -x : x;
    endfunction

    task tb_end_group;
        begin
            if (tb_errors == 0) $display("PASS: %0s", tb_gname(tb_cur));
            else $display("FAIL: %0s -- %0s (%0d mismatches)", tb_gname(tb_cur), tb_detail, tb_errors);
        end
    endtask

    task tb_check;
        begin
            if ((((dispense ^ e_dispense) & m_dispense) !== 0) ||
                (((change ^ e_change) & m_change) !== 0) ||
                (((credit ^ e_credit) & m_credit) !== 0)) begin
                if (tb_errors == 0)
                    $sformat(tb_detail, "vector %0d (t=%t): rst=%h coin=%h -> expected dispense=%h change=%h credit=%h, got dispense=%h change=%h credit=%h",
